interface DateFields { year: number; month: number; day: number; }
class Expiry { year: number = 2023; month: number = 5; day: number = 18; }
function main(): void {
  const date = Temporal.PlainDate.from({ year: 2023, month: 5, day: 18 });
  assert(date.toString() === "2023-05-18", "date bag");
  assert(Temporal.PlainYearMonth.from({ year: 2023, month: 5 }).toString() === "2023-05", "year-month bag");
  assert(Temporal.PlainDate.from(date).equals(date), "date copy");
  assert(Temporal.PlainDate.compare("2023-05-18", "2023-05-19") === -1, "date string compare");
  assert(Temporal.PlainDate.compare({ year: 2023, month: 5, day: 18 }, "2023-05-19") === -1, "mixed date compare");
  assert(date.until("2023-06-01").days === 14, "date string until");
  assert(date.since({ year: 2023, month: 5, day: 17 }).days === 1, "date bag since");
  assert(date.equals({ year: 2023, month: 5, day: 18 }), "date bag equals");
  const fields: DateFields = { year: 2023, month: 5, day: 18 };
  assert(Temporal.PlainDate.from(fields).equals(date), "interface bag");
  assert(Temporal.PlainDate.from(new Expiry()).equals(date), "class fields bag");
  assert(Temporal.PlainYearMonth.from(date).month === 5, "date as year-month bag");
  assert(Temporal.PlainMonthDay.from(date).day === 18, "date as month-day bag");
  const dt = Temporal.PlainDateTime.from({ year: 2023, month: 5, day: 18, hour: 12 });
  assert(dt.hour === 12 && dt.minute === 0, "datetime bag defaults");
  assert(Temporal.PlainDate.from(dt).equals(date), "datetime to date");
  assert(Temporal.PlainDateTime.from(date).hour === 0, "date to datetime defaults midnight");
  assert(dt.equals("2023-05-18T12:00"), "datetime string equals");
  assert(Temporal.PlainDateTime.compare(date, dt) === -1, "datetime mixed compare");
  assert(dt.until({ year: 2023, month: 5, day: 18, hour: 13 }).hours === 1, "datetime bag until");
  assert(dt.since("2023-05-18T11:00").hours === 1, "datetime string since");
  const time = Temporal.PlainTime.from({ hour: 12, minute: 30 });
  assert(time.toString() === "12:30:00", "time bag");
  assert(Temporal.PlainTime.from(dt).hour === 12, "datetime to time");
  assert(time.equals({ hour: 12, minute: 30 }), "time bag equals");
  assert(Temporal.PlainTime.compare("12:00", time) === -1, "time string compare");
  assert(time.until("13:30").hours === 1, "time string until");
  assert(time.since({ hour: 11, minute: 30 }).hours === 1, "time bag since");
  const ym = Temporal.PlainYearMonth.from({ year: 2023, month: 5 });
  assert(ym.equals("2023-05"), "year-month string equals");
  assert(Temporal.PlainYearMonth.compare(ym, { year: 2023, month: 6 }) === -1, "year-month bag compare");
  assert(ym.until("2023-06").months === 1, "year-month string until");
  assert(ym.since({ year: 2023, month: 4 }).months === 1, "year-month bag since");
  const md = Temporal.PlainMonthDay.from({ month: 2, day: 29 });
  assert(md.equals("02-29"), "month-day bag and string");
  assert(Temporal.PlainMonthDay.from(md).equals({ month: 2, day: 29 }), "month-day copy");
  const z = Temporal.ZonedDateTime.from({ year: 2023, month: 5, day: 18, hour: 12, timeZone: "UTC" });
  assert(z.hour === 12 && z.day === 18, "zoned bag");
  assert(Temporal.ZonedDateTime.from(z).equals(z), "zoned copy");
  assert(z.equals("2023-05-18T12:00Z[UTC]"), "zoned string equals");
  assert(Temporal.ZonedDateTime.compare(z, { year: 2023, month: 5, day: 19, timeZone: "UTC" }) === -1, "zoned bag compare");
  assert(z.until("2023-05-18T13:00Z[UTC]").hours === 1, "zoned string until");
  assert(z.since({ year: 2023, month: 5, day: 18, hour: 11, timeZone: "UTC" }).hours === 1, "zoned bag since");
  assert(Temporal.PlainDate.from(z).equals(date), "zoned to date");
  assert(Temporal.PlainTime.from(z).equals({ hour: 12 }), "zoned to time");
  assert(Temporal.PlainDateTime.from(z).equals(dt), "zoned to datetime");
  const instant = Temporal.Instant.from(z);
  assert(instant.equals("2023-05-18T12:00Z"), "instant string equals");
  assert(Temporal.Instant.from(instant).equals(z), "instant copy and zoned equals");
  assert(Temporal.Instant.compare("2023-05-18T11:00Z", z) === -1, "instant mixed compare");
  assert(instant.until("2023-05-18T13:00Z", { largestUnit: "hour" }).hours === 1, "instant string until");
  assert(instant.since(z).seconds === 0, "instant zoned since");
  assert(Temporal.Duration.from({ hours: 1 }).hours === 1, "duration bag");
  assert(Temporal.Duration.compare("PT1H", { minutes: 60 }) === 0, "duration string compare");
  assert(time.add("PT1H").hour === 13, "duration string arithmetic");
}
